------------------
---- MONITORS ----
------------------

-- See https://wiki.hypr.land/Configuring/Basics/Monitors/
hl.monitor({
    output = "",
    mode = "preferred", -- fixed the "preffered" typo from your .conf
    position = "auto",
    scale = 1,
})

hl.env("WLR_DRM_NO_ATOMIC", "1")

---------------------
---- MY PROGRAMS ----
---------------------

-- Set programs that you use
local terminal = "kitty"
local fileManager = "yazi"
local menu = "rofi -show drun"
-- local menu = "kitty --class gyr -e gyr --replace"
-------------------
---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/Configuring/Basics/Autostart/
hl.on("hyprland.start", function()
    -- wallpaper
    hl.exec_cmd("hyprpaper")
    -- Notifications
    hl.exec_cmd("swaync")

    -- Audio services
    -- hl.exec_cmd("pipewire")
    -- hl.exec_cmd("wireplumber")

    -- Portal support (for file pickers etc.)
    hl.exec_cmd("xdg-desktop-portal-hyprland")

    -- Polkit agent (Hypr-native)
    hl.exec_cmd("hyprpolkitagent")

    -- Clipboard history
    hl.exec_cmd("wl-paste --watch cliphist store")
    hl.exec_cmd("wl-paste --type text --watch cliphist store")
    hl.exec_cmd("wl-paste --type image --watch cliphist store")

    -- Bar
    hl.exec_cmd("waybar")

    -- Idle manager (for locking/suspend etc.)
    hl.exec_cmd("sleep 1 && hypridle")

    -- Night light
    -- hl.exec_cmd("sleep 1 && hyprsunset")

    -- QT theming support
    hl.exec_cmd("sleep 1 && hyprqtsupport")

    -- activity watch for screen time and stuff
    hl.exec_cmd("firejail --net=none aw-qt")
end)

